const reason = $json.token_error || 'ACCEPT_TOKEN_REJECTED';

return [{
  json: {
    ok: false,
    accepted: false,
    status: 'REJECTED_SECURITY_VALIDATION',
    error_code: reason,
    message: 'Proposal acceptance link is invalid or expired.',
    lead_id: $json.accept_token_lead_id ?? null,
    rejected_at: new Date().toISOString(),
    security_event: {
      type: 'proposal_accept_token_rejected',
      reason
    }
  }
}];
